// Cliopatria polities and groupings as entities (generated by scripts/import-polities.ts).
// Stories name the polities they are about; a grouping stands for its member polities in the years they belong to it.
import catalogue from './polities.json';

export type Polity=(typeof catalogue.polities)[number];
export type Grouping=(typeof catalogue.groupings)[number];
export const polities=catalogue.polities,groupings=catalogue.groupings;
const byName=new Map<string,Polity|Grouping>([...polities,...groupings].map(p=>[p.name,p]));
const byId=new Map<string,Polity|Grouping>([...polities,...groupings].map(p=>[p.id,p]));
const isGrouping=(p:Polity|Grouping):p is Grouping=>'members' in p;

export function polityEntity(name:string){
 const p=byName.get(name);
 if(!p)throw new Error(`Unknown Cliopatria polity “${name}”`);
 return {id:p.id,name:p.name,kind:'polity' as const};
}
export const polityById=(id:string)=>byId.get(id);

// Map polity names to outline in a year for these entity IDs. Other entities (people, sketched city-states) add nothing.
export function polityNamesAt(entityIds:string[],year:number){
 const names=new Set<string>();
 for(const id of entityIds){
  const p=byId.get(id);if(!p)continue;
  if(!isGrouping(p)){names.add(p.name);continue}
  for(const m of p.members)if(m.ranges.some(([f,t])=>f<=year&&year<=t))names.add(m.name);
 }
 return [...names];
}
// Every map polity these entity IDs can stand for, in any year.
export function polityNames(entityIds:string[]){
 return [...new Set(entityIds.flatMap(id=>{const p=byId.get(id);return !p?[]:isGrouping(p)?p.members.map(m=>m.name):[p.name]}))];
}

// The map polities a span is about and the years it shows each: the span's dates, narrowed for a grouping member
// to the years Cliopatria lists it in the grouping.
export function spanPolities(span:{entityIds:string[];interval:{start:{latest:number};end:{earliest:number};endExclusive:boolean}}){
 const first=span.interval.start.latest,last=span.interval.endExclusive?span.interval.end.earliest-1:span.interval.end.earliest;
 const ranges=new Map<string,[number,number][]>();
 const add=(name:string,[f,t]:number[])=>{const from=Math.max(f,first),to=Math.min(t,last);if(from<=to)ranges.set(name,[...(ranges.get(name)??[]),[from,to]])};
 for(const id of span.entityIds){const p=byId.get(id);if(!p)continue;if(isGrouping(p))for(const m of p.members)m.ranges.forEach(r=>add(m.name,r));else add(p.name,[first,last])}
 return [...ranges].flatMap(([name,list])=>list.sort((a,b)=>a[0]-b[0]).reduce<[number,number][]>((out,[f,t])=>{const l=out.at(-1);if(l&&f<=l[1]+1)l[1]=Math.max(l[1],t);else out.push([f,t]);return out},[]).map(([from,to])=>({name,from,to})));
}

// Search entries: the bare name of a grouping, with its member count, alongside the polities themselves.
export type PolityEntry={id:string;name:string;from:number;to:number;peak:number;subtitle:string};
export const politySearch:PolityEntry[]=[
 ...groupings.map(g=>({id:g.id,name:g.name.slice(1,-1),from:g.from,to:g.to,peak:g.peak,subtitle:`Cliopatria grouping of ${g.members.length} polities`})),
 ...polities.map(p=>({id:p.id,name:p.name,from:p.from,to:p.to,peak:p.peak,subtitle:'Cliopatria polity'}))
];
